type LRUCache struct {
    cap        int
    m          map[int]*node
    head, tail *node // 哨兵节点
}

type node struct {
    key, val   int
    prev, next *node
}

func Constructor(capacity int) LRUCache {
    head := &node{}
    tail := &node{}
    head.next = tail
    tail.prev = head
    return LRUCache{cap: capacity, m: make(map[int]*node), head: head, tail: tail}
}

func (c *LRUCache) Get(key int) int {
    if n, ok := c.m[key]; ok {
        c.moveToHead(n)
        return n.val
    }
    return -1
}

func (c *LRUCache) Put(key int, value int) {
    if n, ok := c.m[key]; ok {
        n.val = value
        c.moveToHead(n)
        return
    }
    n := &node{key: key, val: value}
    c.m[key] = n
    c.addToHead(n)
    if len(c.m) > c.cap {
        removed := c.removeTail()
        delete(c.m, removed.key)
    }
}

func (c *LRUCache) addToHead(n *node) {
    n.prev = c.head
    n.next = c.head.next
    c.head.next.prev = n
    c.head.next = n
}

func (c *LRUCache) removeNode(n *node) {
    n.prev.next = n.next
    n.next.prev = n.prev
}

func (c *LRUCache) moveToHead(n *node) {
    c.removeNode(n)
    c.addToHead(n)
}

func (c *LRUCache) removeTail() *node {
    n := c.tail.prev
    c.removeNode(n)
    return n
}
